using DSWI_T1_1.Models; using Microsoft.EntityFrameworkCore; namespace DSWI_T1_1.Data; public class ClinicaDbContext:DbContext { public ClinicaDbContext(DbContextOptions<ClinicaDbContext> options):base(options){} public DbSet<Paciente> Pacientes=>Set<Paciente>(); public DbSet<Cita> Citas=>Set<Cita>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Paciente>(e=>{e.ToTable("Pacientes");e.HasKey(x=>x.PacienteID);e.Property(x=>x.Nombre).HasMaxLength(100);e.Property(x=>x.DNI).HasMaxLength(20);});b.Entity<Cita>(e=>{e.ToTable("Citas");e.HasKey(x=>x.CitaID);e.Property(x=>x.Especialidad).HasMaxLength(50);e.Property(x=>x.Estado).HasMaxLength(20);e.HasOne(x=>x.Paciente).WithMany(x=>x.Citas).HasForeignKey(x=>x.PacienteID);});}}